    if (hsl.h < 0.14) return 'ember-fire';
    if (hsl.h < 0.18) return 'golden-hour';
    if (hsl.h < 0.42) return 'cyber-forest';
    if (hsl.h < 0.66) return 'arctic-aurora';
    if (hsl.h < 0.74) return 'ocean-deep';
